/* LifeOS Planner — original offline-first personal life management app. */
(function(){
'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const todayISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const id=()=>`r_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateObj=v=>{if(!v)return new Date();const d=new Date(`${v}T12:00:00`);return Number.isNaN(d.getTime())?new Date():d;};
const fmtDate=(v,opts={month:'short',day:'numeric'})=>dateObj(v).toLocaleDateString(LifeOSI18n.locale(),opts);
const addDays=(iso,n)=>{const d=dateObj(iso);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const startOfWeek=(iso)=>{const d=dateObj(iso);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const money=n=>{const amount=Number(n||0);try{return new Intl.NumberFormat(LifeOSI18n.locale(),{style:'currency',currency:state.settings.currency||'USD',maximumFractionDigits:2}).format(amount);}catch(e){return `$${amount.toFixed(2)}`;}};
const t=k=>LifeOSI18n.t(k);
// Display translations are presentation-only. Personal text stays exactly as entered.
function recordText(record,value){const raw=String(value??'');const shown=(record?.demo||record?.systemText)?LifeOSI18n.tx(raw):raw;return `<span class="user-entered">${esc(shown)}</span>`;}
function enumText(value){return esc(LifeOSI18n.tx(String(value??'')));}
function formDisplayValue(record,fieldName,value,fieldType='text'){if(!record?.demo||value==null||['select','date','time','number','url'].includes(fieldType))return value;if(Array.isArray(value))return value.map(x=>LifeOSI18n.tx(String(x))).join('\n');return LifeOSI18n.tx(String(value));}

let state={settings:{name:'Your space',theme:'blush',language:'en',currency:'USD',year:2027,monthlyBudget:0,cycleLength:28,fontSize:'extra-large',density:'comfortable'},records:[]};
let route='dashboard',selectedDate=todayISO(),activeModalSave=null,photoTarget=null,objectURLs=new Map();
const definitions={
 task:{title:'Task',fields:[['title','Task name','text',true],['date','Date','date',false],['time','Time','time'],['priority','Priority','select',['Low','Normal','High']],['category','Category','select',['Personal','Work','Family','Errands']],['notes','Notes','textarea']]},
 event:{title:'Event',fields:[['title','Event name','text',true],['date','Date','date',true],['time','Time','time'],['kind','Type','select',['Personal','Work','Family','School','Appointment','Birthday']],['notes','Notes','textarea']]},
 habit:{title:'Habit',fields:[['title','Habit name','text',true],['category','Category','select',['Health','Personal','Work','Home','Mindfulness']],['notes','Why it matters','textarea']]},
 routine:{title:'Routine',fields:[['title','Routine name','text',true],['period','When','select',['Morning','Night','Custom']],['steps','Steps (one per line)','textarea',true],['notes','Notes','textarea']]},
 glow:{title:'Glow-up challenge',fields:[['title','Challenge name','text',true],['startDate','Start date','date',true],['duration','Duration (days)','number',true],['notes','Intention','textarea']]},
 skincare:{title:'Skincare routine item',fields:[['title','Product or step','text',true],['frequency','When','select',['AM','PM','AM & PM','Weekly']],['notes','Notes','textarea']]},
 cycle:{title:'Cycle log',fields:[['startDate','Period start date','date',true],['endDate','Period end date','date'],['symptoms','Symptoms','text'],['notes','Notes','textarea']]},
 wellness:{title:'Wellness check-in',fields:[['kind','Metric','select',['Mood','Sleep (hours)','Water (glasses)','Steps','Workout']],['date','Date','date',true],['value','Value / note','text',true],['notes','Notes','textarea']]},
 finance:{title:'Money transaction',fields:[['kind','Type','select',['Income','Expense']],['date','Date','date',true],['title','Description','text',true],['amount','Amount','number',true],['category','Category','select',['Home','Food','Transport','Shopping','Health','Bills','Work','Personal','Other']],['notes','Notes','textarea']]},
 financeGoal:{title:'Savings goal',fields:[['title','Goal name','text',true],['target','Target amount','number',true],['saved','Amount saved','number',true],['dueDate','Target date','date'],['notes','Notes','textarea']]},
 meal:{title:'Meal plan',fields:[['date','Date','date',true],['meal','Meal','select',['Breakfast','Lunch','Dinner','Snack']],['recipe','Meal / recipe','text',true],['notes','Notes','textarea']]},
 grocery:{title:'Grocery item',fields:[['title','Item','text',true],['category','Category','select',['Produce','Dairy','Protein','Pantry','Frozen','Household','Other']],['date','Needed by','date']]},
 recipe:{title:'Recipe card',fields:[['title','Recipe name','text',true],['ingredients','Ingredients','textarea',true],['instructions','Instructions','textarea'],['notes','Prep time / servings','text']]},
 goal:{title:'Goal',fields:[['title','Goal name','text',true],['why','Why this matters','textarea'],['action','Next action','text'],['progress','Progress (%)','number'],['dueDate','Target date','date']]},
 vision:{title:'Vision board item',fields:[['title','Vision / intention','text',true],['category','Area of life','select',['Career','Health','Home','Relationships','Travel','Money','Personal']],['notes','Why it matters','textarea']]},
 journal:{title:'Journal entry',fields:[['date','Date','date',true],['title','Entry title','text'],['mood','Mood','select',['Happy','Calm','Grateful','Hopeful','Tired','Stressed','Sad','Anxious','Neutral']],['gratitude','Today I am grateful for','textarea'],['content','Journal entry','textarea']]},
 book:{title:'Book',fields:[['title','Book title','text',true],['author','Author','text'],['status','Reading status','select',['Want to read','Currently reading','Finished','Paused']],['rating','Rating (1–5)','number'],['goal','Reading goal / notes','text']]},
 outfit:{title:'Outfit diary entry',fields:[['date','Date','date',true],['title','Outfit / occasion','text',true],['notes','Details','textarea']]},
 wishlist:{title:'Wishlist item',fields:[['title','Item','text',true],['category','Category','select',['Clothing','Beauty','Home','Tech','Books','Other']],['price','Price','number'],['url','Product link','url'],['notes','Notes','textarea']]},
 weekly:{title:'Weekly focus',fields:[['weekStart','Week starting','date',true],['focus','Weekly focus','textarea'],['review','Weekly reflection','textarea']]}
};
function records(type){return state.records.filter(r=>r.type===type);}
function byId(recordId){return state.records.find(r=>r.id===recordId);}
async function persist(){window.LifeOSSettings=state.settings;await LifeOSDB.saveState(state);await updateHeader();}
function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=LifeOSI18n.tx(message);$('#toastRegion').append(el);setTimeout(()=>el.remove(),3000);}
function displayName(){const raw=state.settings.name||'Your space';return raw==='Your space'?t('yourPrivateSpace'):raw;}
async function updateHeader(){
 const name=displayName(),initial=(name.trim()[0]||'U').toUpperCase();
 $('#sidebarName').textContent=name;$('#topName').textContent=name;
 const photoUrl=state.settings.profilePhotoId?await imageURL(state.settings.profilePhotoId):'';
 ['#avatarInitial','#topAvatar','#profilePhotoPreview'].forEach(sel=>{const el=$(sel);if(!el)return;el.innerHTML=photoUrl?`<img src="${photoUrl}" alt="Profile photo">`:`<span>${esc(initial)}</span>`;});
 $('#todayCount').textContent=records('task').filter(x=>x.date===todayISO()&&!x.done).length;
}
async function updateProfilePreview(){const el=$('#profilePhotoPreview');if(!el)return;const url=state.settings.profilePhotoId?await imageURL(state.settings.profilePhotoId):'';const initial=(displayName().trim()[0]||'U').toUpperCase();el.innerHTML=url?`<img src="${url}" alt="Profile photo">`:`<span>${esc(initial)}</span>`;}

function applyTheme(){const fs=state.settings.fontSize||'extra-large',density=state.settings.density||'comfortable',theme=state.settings.theme||'blush';document.body.className=`theme-${theme} text-${fs} density-${density}`;document.documentElement.lang=state.settings.language||'en';document.body.dir=state.settings.language==='ar'?'rtl':'ltr';LifeOSI18n.apply();const topLang=$('#topLanguage');if(topLang)topLang.value=state.settings.language||'en';$$('#topbarThemes [data-theme]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.theme===theme));});}
function navActive(){ $$('.nav-item[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));const active=$(`.nav-item[data-route="${route}"]`);$('#breadcrumbCurrent').textContent=active?active.textContent.trim():t('settingsBackup');}
function pageHeader(title,desc,actions=''){return `<div class="page-heading"><div><p class="eyebrow">LIFEOS · ${esc(title.toUpperCase())}</p><h1>${esc(title)}</h1><p>${esc(desc||'')}</p></div><div class="heading-actions">${actions}</div></div>`;}
function card(title,body,subtitle='',extra=''){return `<section class="card ${extra}"><div class="card-head"><div><h2 class="card-title">${title}</h2>${subtitle?`<p class="card-subtitle">${subtitle}</p>`:''}</div></div>${body}</section>`;}
function empty(title='Nothing here yet',desc='Add your first item to get started.',button=''){return `<div class="empty-state"><div class="empty-icon">✧</div><strong>${esc(title)}</strong><p>${esc(desc)}</p>${button}</div>`;}
function addBtn(label,action='add',type='',cls='btn-primary'){return `<button class="btn ${cls}" data-action="${action}" ${type?`data-type="${type}"`:''}>＋ ${esc(label)}</button>`;}
function editDelete(r){return `<span class="row-actions">${definitions[r.type]?`<button class="icon-action" data-action="edit" data-id="${r.id}" title="Edit">✎</button>`:''}<button class="icon-action" data-action="delete" data-id="${r.id}" title="Delete">×</button></span>`;}
function taskRow(r){return `<div class="list-row"><input class="check" type="checkbox" data-action="toggle-task" data-id="${r.id}" ${r.done?'checked':''} aria-label="Complete task"><div class="list-main"><strong style="${r.done?'text-decoration:line-through;opacity:.55':''}">${recordText(r,r.title)}</strong><small>${esc(r.time||'')} ${r.category?`· ${enumText(r.category)}`:''} ${r.priority?`· ${enumText(r.priority+' priority')}`:''}</small></div>${r.priority==='High'?`<span class="tag">${enumText('High')}</span>`:''}${editDelete(r)}</div>`;}
function itemRows(list,emptyTitle='Nothing here yet',emptyDesc='Add your first item to get started.'){return list.length?`<div class="item-list">${list.map(r=>`<div class="list-row"><div class="list-main"><strong>${recordText(r,r.title||r.recipe||r.item||'Untitled')}</strong><small>${recordText(r,r.subtitle||r.notes||r.date||'')}</small></div>${editDelete(r)}</div>`).join('')}</div>`:empty(emptyTitle,emptyDesc);}
function metric(label,value,foot,icon,variant=''){return `<div class="card metric-card ${variant}"><div class="metric-top"><span>${esc(label)}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${esc(foot)}</div></div>`;}
function dateText(iso=todayISO()){return dateObj(iso).toLocaleDateString(LifeOSI18n.locale(),{weekday:'long',month:'long',day:'numeric',year:'numeric'});}
async function renderDashboard(){
 const today=todayISO(),name=displayName();
 const tasks=records('task').filter(r=>r.date===today),open=tasks.filter(r=>!r.done),doneTasks=tasks.filter(r=>r.done).length;
 const habits=records('habit'),doneHabits=habits.filter(h=>(h.logs||[]).includes(today)).length;
 const denominator=tasks.length+habits.length,score=denominator?Math.round(((doneTasks+doneHabits)/denominator)*100):0;
 const month=today.slice(0,7),transactions=records('finance').filter(r=>(r.date||'').startsWith(month));
 const income=transactions.filter(r=>r.kind==='Income').reduce((a,r)=>a+Number(r.amount||0),0),expense=transactions.filter(r=>r.kind==='Expense').reduce((a,r)=>a+Number(r.amount||0),0);
 const goals=records('financeGoal'),goalTotal=goals.reduce((a,g)=>a+Number(g.target||0),0),goalSaved=goals.reduce((a,g)=>a+Number(g.saved||0),0);
 const priorities=open.slice().sort((a,b)=>({High:0,Normal:1,Low:2}[a.priority]??1)-({High:0,Normal:1,Low:2}[b.priority]??1)).slice(0,3);
 const upcoming=records('event').filter(r=>r.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||'')).slice(0,3);
 const heroRecord=records('glowPhoto').find(x=>x.moment==='Dashboard');
 const heroURL=await imageURL(heroRecord?.photoId);
 const greeting=LifeOSI18n.greeting();
 const dailyQuote=LifeOSI18n.quoteForDate(today);
 const art=`<img class="hero-photo ${heroURL?'user-hero-photo':'built-in-hero'}" src="${heroURL||'assets/images/lifeos-hero-bedroom.jpg'}" alt="${heroURL?'Your LifeOS dashboard photo':'A warm, sunlit bedroom and reading nook'}">`;
 const habitRows=habits.slice(0,5).map(h=>`<div class="dashboard-habit-row"><span class="habit-emoji">${h.category==='Health'?'♡':h.category==='Work'?'✧':h.category==='Home'?'⌂':'☼'}</span><div class="dashboard-row-main"><strong>${recordText(h,h.title)}</strong><small>${(h.logs||[]).length} check-ins</small></div><input class="check" type="checkbox" data-action="toggle-habit" data-id="${h.id}" ${(h.logs||[]).includes(today)?'checked':''} aria-label="Complete ${esc(h.title)}"></div>`).join('');
 const upcomingRows=upcoming.map(e=>`<div class="dashboard-event-row"><div class="event-date-tile"><strong>${dateObj(e.date).getDate()}</strong><small>${dateObj(e.date).toLocaleDateString(LifeOSI18n.locale(),{month:'short'})}</small></div><div class="dashboard-row-main"><strong>${recordText(e,e.title)}</strong><small>${esc(e.time||enumText('All day'))} · ${enumText(e.kind||'Event')}</small></div>${editDelete(e)}</div>`).join('');
 return `<section class="dashboard-page">
  <div class="dashboard-heading"><div><p class="eyebrow">LIFEOS · YOUR PERSONAL SPACE</p><h1>Your glow dashboard</h1><p>${dateText()} <span class="heading-dot">✦</span> A gentle overview of the life you're building.</p></div><div class="dashboard-heading-actions"><button class="btn btn-secondary" data-action="print">↗ Print / PDF</button><button class="btn btn-primary" data-action="add" data-type="task">＋ Add a task</button></div></div>
  <section class="welcome-hero"><div class="welcome-art">${art}<span class="art-label">A LITTLE SPACE FOR YOU</span><button class="hero-photo-button" data-action="photo" data-moment="Dashboard">${heroURL?'Change photo':'＋ Add your photo'}</button></div><div class="welcome-copy"><p class="eyebrow">YOUR DAY, YOUR PACE</p><h2>${greeting}, <em>${esc(name)}</em> <span class="sparkle">✦</span></h2><p class="hero-affirmation">“${esc(dailyQuote)}”</p><p class="hero-description">You don't have to do everything today. Just make room for the things that matter.</p><div class="hero-chips"><span>♡ Be kind to yourself</span><span>✧ Progress over perfection</span></div><div class="hero-links"><button data-action="open-route" data-route="today">Today’s plan <span>→</span></button><button data-action="open-route" data-route="journal">Journal <span>→</span></button><button data-action="open-route" data-route="goals">Vision board <span>→</span></button></div></div></section>
  <div class="dashboard-section-label"><div><p class="eyebrow">YOUR OVERVIEW</p><h2>A little progress adds up</h2></div><span class="date-chip">${fmtDate(today,{month:'long',day:'numeric'})}</span></div>
  <div class="dashboard-overview-grid">
   <section class="dashboard-card glow-score-panel"><div class="dashboard-card-head"><div><p class="eyebrow">TODAY'S ENERGY</p><h3>Your glow score</h3></div><span class="soft-icon">✧</span></div><div class="score-content"><div class="score-ring" style="--score:${score}%"><div><strong>${score}</strong><small> / 100</small></div></div><div class="score-copy"><strong>${score>=80?'You’re glowing':score>=45?'Finding your rhythm':score>0?'One step at a time':'A fresh start'}</strong><span>${doneTasks} of ${tasks.length} tasks · ${doneHabits} of ${habits.length} habits</span></div></div><div class="score-foot"><span>Every small step counts</span><span>♡</span></div></section>
   <section class="dashboard-card priorities-panel"><div class="dashboard-card-head"><div><p class="eyebrow">THE IMPORTANT THINGS</p><h3>Today’s top 3</h3></div><button class="text-link" data-action="open-route" data-route="today">View all →</button></div>${priorities.length?`<div class="dashboard-priority-list">${priorities.map((r,i)=>`<div class="dashboard-priority-row"><span class="priority-number">0${i+1}</span><input class="check" type="checkbox" data-action="toggle-task" data-id="${r.id}" ${r.done?'checked':''} aria-label="Complete task"><div class="dashboard-row-main"><strong>${recordText(r,r.title)}</strong><small>${esc(r.time||enumText('Anytime'))} ${r.priority==='High'?`· ${enumText('High priority')}`:''}</small></div>${editDelete(r)}</div>`).join('')}</div>`:empty('Your priorities will live here','Add up to three important things for today.',addBtn('Add a priority','add','task','btn-secondary'))}</section>
   <section class="dashboard-card habits-panel"><div class="dashboard-card-head"><div><p class="eyebrow">TINY DAILY PROMISES</p><h3>Habits today</h3></div><span class="tag sage">${doneHabits}/${habits.length} done</span></div>${habits.length?`<div class="dashboard-habits-list">${habitRows}</div><div class="habit-progress-track"><span style="width:${habits.length?doneHabits/habits.length*100:0}%"></span></div><div class="habit-progress-label">${habits.length?Math.round(doneHabits/habits.length*100):0}% of your habits checked in</div>`:empty('Start with one small habit','A simple daily rhythm can change a lot.',addBtn('Add a habit','add','habit','btn-secondary'))}</section>
  </div>
  <div class="dashboard-bottom-grid"><section class="dashboard-card upcoming-panel"><div class="dashboard-card-head"><div><p class="eyebrow">LOOKING AHEAD</p><h3>Coming up</h3></div><button class="text-link" data-action="open-route" data-route="month">Open calendar →</button></div>${upcomingRows||empty('Nothing on the calendar yet','Add a date you want to remember.',addBtn('Add an event','add','event','btn-secondary'))}</section><section class="dashboard-card money-panel"><div class="dashboard-card-head"><div><p class="eyebrow">MONEY AT A GLANCE</p><h3>This month</h3></div><span class="soft-icon">＄</span></div><div class="money-total">${money(income-expense)}</div><p class="money-caption">Monthly net balance</p><div class="money-split"><div><span>Income</span><strong class="amount-positive">${money(income)}</strong></div><div><span>Expenses</span><strong class="amount-negative">${money(expense)}</strong></div></div><button class="text-link money-link" data-action="open-route" data-route="finance">Open finance →</button></section></div>
 </section>`;
}
async function renderToday(){const today=todayISO(),tasks=records('task').filter(r=>r.date===today).sort((a,b)=>(a.time||'').localeCompare(b.time||'')),events=records('event').filter(r=>r.date===today).sort((a,b)=>(a.time||'').localeCompare(b.time||'')),well=records('wellness').filter(r=>r.date===today),todayPhotoRecord=records('glowPhoto').find(x=>x.moment==='Today'&&x.date===today),todayPhotoURL=await imageURL(todayPhotoRecord?.photoId);return `${pageHeader('Today',dateText(),`${addBtn('Add task','add','task')}${addBtn('Add event','add','event','btn-secondary')}`)}<div class="grid grid-2"><div class="grid" style="align-content:start">${card('Your to-do list',tasks.length?`<div class="item-list">${tasks.map(taskRow).join('')}</div>`:empty('A fresh page','Add the tasks you want to focus on today.',addBtn('Add a task','add','task')),'Check off one thing at a time.')}${card('Today’s schedule',events.length?`<div class="item-list">${events.map(e=>`<div class="list-row"><span class="tag sage">${esc(e.time||'Anytime')}</span><div class="list-main"><strong>${recordText(e,e.title)}</strong><small>${enumText(e.kind||'Personal')} ${e.notes?`· ${recordText(e,e.notes)}`:''}</small></div>${editDelete(e)}</div>`).join('')}</div>`:empty('No events on the calendar','Appointments and important dates appear here.',addBtn('Add an event','add','event')))}</div><div class="grid" style="align-content:start">${card('Daily wellness check-in',`<div class="grid grid-2">${['Mood','Sleep (hours)','Water (glasses)','Steps','Workout'].map(k=>{const entry=well.filter(x=>x.kind===k).at(-1),val=entry?.value||'—';return `<div class="card" style="padding:12px;background:var(--surface-2)"><div class="small muted">${enumText(k)}</div><strong style="display:block;font-family:Georgia,serif;font-size:18px;margin:7px 0">${entry?recordText(entry,val):esc(val)}</strong><button class="btn btn-secondary btn-small" data-action="add" data-type="wellness" data-kind="${esc(k)}">Update</button></div>`}).join('')}</div>`,`A quick note about how you’re doing.`)}${card('Photo of the day',todayPhotoURL?`<div class="photo-box"><img src="${todayPhotoURL}" alt="Photo of the day"></div><div style="display:flex;justify-content:flex-end;margin-top:9px"><button class="btn btn-secondary btn-small" data-action="photo" data-moment="Today">Change photo</button></div>`:`<div class="photo-box" style="min-height:150px"><div style="text-align:center"><div style="font-size:26px;margin-bottom:8px">✿</div><button class="btn btn-secondary btn-small" data-action="photo" data-moment="Today">＋ Add today’s photo</button></div></div>`,'A small moment worth remembering.')}${card('Daily focus',`<textarea class="search-input" id="dailyFocus" rows="4" placeholder="What would make today feel meaningful?">${esc(records('dailyFocus').find(x=>x.date===today)?.text||'')}</textarea><div style="display:flex;justify-content:flex-end;margin-top:9px"><button class="btn btn-primary btn-small" data-action="save-focus">Save focus</button></div>`,'Keep it simple and kind.')}</div></div>`;}
function renderWeek(){const start=startOfWeek(todayISO()),days=Array.from({length:7},(_,i)=>addDays(start,i)),events=records('event'),tasks=records('task'),weekly=records('weekly').find(x=>x.weekStart===start);return `${pageHeader('Week',`${fmtDate(start)} — ${fmtDate(days[6])}`,`${addBtn('Add task','add','task')}${addBtn('Add event','add','event','btn-secondary')}`)}<div class="two-column"><div>${card('Your week',days.map(d=>{const es=events.filter(x=>x.date===d),ts=tasks.filter(x=>x.date===d);return `<div class="week-row"><div class="week-label"><strong>${dateObj(d).toLocaleDateString(LifeOSI18n.locale(),{weekday:'short'})}</strong><br>${fmtDate(d,{month:'short',day:'numeric'})}${d===todayISO()?'<br><span class="tag">Today</span>':''}</div><div class="week-content">${ts.map(x=>`<span class="mini-event ${x.done?'sage':''}" title="${esc(x.title)}">${x.done?'✓ ':''}${recordText(x,x.title)}</span>`).join('')}${es.map(x=>`<span class="mini-event gold">${esc(x.time?x.time+' · ':'')}${recordText(x,x.title)}</span>`).join('')}${!ts.length&&!es.length?'<span class="muted small">A little open space</span>':''}</div></div>`}).join(''),'Your tasks and calendar events, Monday through Sunday.')}</div><div class="grid" style="align-content:start">${card('Weekly focus',`<form id="weeklyForm" class="form-grid"><div class="field full"><label>What matters most this week?</label><textarea name="focus" rows="4" placeholder="My focus this week…">${esc(weekly?.focus||'')}</textarea></div><div class="field full"><label>Weekly reflection</label><textarea name="review" rows="4" placeholder="What went well? What can I adjust?">${esc(weekly?.review||'')}</textarea></div><div class="field full"><button class="btn btn-primary">Save weekly notes</button></div></form>`,'Plan with intention, then reflect without judgment.')}${card('Weekly snapshot',`<div class="stat-line"><span>Tasks planned</span><strong>${tasks.filter(x=>x.date>=start&&x.date<=days[6]).length}</strong></div><div class="stat-line"><span>Tasks completed</span><strong>${tasks.filter(x=>x.date>=start&&x.date<=days[6]&&x.done).length}</strong></div><div class="stat-line"><span>Calendar events</span><strong>${events.filter(x=>x.date>=start&&x.date<=days[6]).length}</strong></div>`)}</div></div>`;}
function calendarHTML(year,month,selected){const first=new Date(year,month,1),offset=(first.getDay()+6)%7,daysIn=new Date(year,month+1,0).getDate(),prevDays=new Date(year,month,0).getDate();const weekdays=Array.from({length:7},(_,i)=>new Intl.DateTimeFormat(LifeOSI18n.locale(),{weekday:'short'}).format(new Date(2024,0,1+i)));let html=weekdays.map(x=>`<div class="calendar-head">${esc(x)}</div>`).join('');for(let i=0;i<42;i++){let day,dt,muted=false;if(i<offset){day=prevDays-offset+i+1;dt=new Date(year,month-1,day);muted=true;}else if(i>=offset+daysIn){day=i-(offset+daysIn)+1;dt=new Date(year,month+1,day);muted=true;}else{day=i-offset+1;dt=new Date(year,month,day);}const iso=`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`,has=records('event').filter(x=>x.date===iso),tasks=records('task').filter(x=>x.date===iso);html+=`<button class="calendar-day ${muted?'muted-day':''} ${iso===todayISO()?'today':''} ${iso===selected?'selected':''}" data-action="select-date" data-date="${iso}"><span class="day-num">${day}</span><span class="day-dots">${has.slice(0,2).map(()=>'<i class="day-dot"></i>').join('')}${tasks.slice(0,2).map(()=>'<i class="day-dot sage"></i>').join('')}</span></button>`;}return html;}
function renderMonth(){const d=dateObj(selectedDate),year=d.getFullYear(),month=d.getMonth(),events=records('event').filter(x=>x.date===selectedDate),tasks=records('task').filter(x=>x.date===selectedDate);return `${pageHeader('Month','A clear view of your dates and commitments.',`${addBtn('Add event','add','event')}`)}<div class="two-column"><div class="card"><div class="card-head"><div class="month-controls"><button class="icon-button" data-action="month-prev">‹</button><strong>${d.toLocaleDateString(LifeOSI18n.locale(),{month:'long',year:'numeric'})}</strong><button class="icon-button" data-action="month-next">›</button></div><button class="btn btn-secondary btn-small" data-action="month-today">Today</button></div><div class="calendar">${calendarHTML(year,month,selectedDate)}</div><p class="card-subtitle" style="margin-top:12px">Pink dots represent events · Green dots represent tasks.</p></div><div class="grid" style="align-content:start">${card(fmtDate(selectedDate,{weekday:'long',month:'long',day:'numeric'}),`${events.length?`<div class="item-list">${events.map(e=>`<div class="list-row"><div class="list-main"><strong>${recordText(e,e.title)}</strong><small>${esc(e.time||enumText('All day'))} · ${enumText(e.kind||'Personal')}</small></div>${editDelete(e)}</div>`).join('')}</div>`:empty('No events selected','Add an event to this date.',addBtn('Add event','add','event'))}`,'Calendar events')}${card('Tasks for this date',tasks.length?`<div class="item-list">${tasks.map(taskRow).join('')}</div>`:empty('No tasks planned','Add a task for this date.',`<button class="btn btn-secondary btn-small" data-action="add" data-type="task">Add task</button>`) )}</div></div>`;}
function renderYear(){const year=Number(state.settings.year)||2027;const months=Array.from({length:12},(_,i)=>{const count=records('event').filter(x=>x.date?.startsWith(`${year}-${String(i+1).padStart(2,'0')}`)).length;const goals=records('goal').filter(x=>x.dueDate?.startsWith(`${year}-${String(i+1).padStart(2,'0')}`)).length;return `<button class="card" style="text-align:left;border:1px solid var(--line);cursor:pointer" data-action="open-month" data-month="${i}"><div class="card-head"><h3 class="card-title">${new Date(year,i,1).toLocaleDateString(LifeOSI18n.locale(),{month:'long'})}</h3><span class="tag gray">${count} events</span></div><div class="small muted">${goals} goal deadlines</div><div class="calendar" style="margin-top:10px;grid-template-columns:repeat(7,1fr);gap:3px">${Array.from({length:7},(_,i)=>new Intl.DateTimeFormat(LifeOSI18n.locale(),{weekday:'narrow'}).format(new Date(2024,0,1+i))).map(x=>`<span class="calendar-head">${esc(x)}</span>`).join('')}${(()=>{let off=(new Date(year,i,1).getDay()+6)%7,days=new Date(year,i+1,0).getDate(),s='';for(let a=0;a<off;a++)s+='<span></span>';for(let a=1;a<=days;a++)s+=`<span style="font-size:8px;text-align:center;padding:3px 0;border-radius:5px;background:${a===new Date().getDate()&&i===new Date().getMonth()&&year===new Date().getFullYear()?'var(--accent-soft)':'transparent'}">${a}</span>`;return s;})()}</div></button>`}).join('');return `${pageHeader('Year','Your year at a glance. Choose a month to explore.',`<label class="tag">Planner year <select id="yearSelect" style="border:0;background:transparent;color:inherit;font-size:10px;font-weight:700">${[2026,2027,2028,2029,2030].map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label>`)}<div class="grid grid-3">${months}</div><div class="card" style="margin-top:15px"><div class="card-head"><h2 class="card-title">Yearly vision</h2><button class="btn btn-secondary btn-small" data-action="add" data-type="goal">＋ Add yearly goal</button></div>${records('goal').length?`<div class="item-list">${records('goal').map(g=>`<div class="list-row"><div class="list-main"><strong>${recordText(g,g.title)}</strong><small>${esc(g.dueDate||enumText('No target date'))} · ${Number(g.progress||0)}% ${enumText('complete')}</small><div class="progress-track" style="margin-top:6px"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,Number(g.progress||0)))}%"></div></div></div>${editDelete(g)}</div>`).join('')}</div>`:empty('Give the year a direction','Add a few goals that feel meaningful.',addBtn('Add a goal','add','goal'))}</div>`;}
function streak(logs=[]){let n=0,d=todayISO();if(!logs.includes(d))d=addDays(d,-1);while(logs.includes(d)&&n<366){n++;d=addDays(d,-1);}return n;}
function renderHabits(){const today=todayISO(),habits=records('habit'),days=Array.from({length:7},(_,i)=>addDays(todayISO(),i-6));return `${pageHeader('Habits','Build consistency gently. Progress is more important than perfection.',addBtn('Add habit','add','habit'))}<div class="grid grid-2">${habits.length?habits.map(h=>`<section class="card"><div class="card-head"><div><h2 class="card-title">${recordText(h,h.title)}</h2><p class="card-subtitle">${enumText(h.category||'Personal')} · ${enumText(`${streak(h.logs||[])} day streak`)}</p></div>${editDelete(h)}</div><div class="habit-grid">${days.map(d=>`<button class="habit-day ${(h.logs||[]).includes(d)?'done':''} ${d===today?'today':''}" data-action="habit-day" data-id="${h.id}" data-date="${d}" title="${fmtDate(d)}">${dateObj(d).toLocaleDateString(LifeOSI18n.locale(),{weekday:'narrow'})}<br>${dateObj(d).getDate()}</button>`).join('')}</div><div class="progress-track" style="margin-top:12px"><div class="progress-fill sage" style="width:${Math.round((days.filter(d=>(h.logs||[]).includes(d)).length/7)*100)}%"></div></div><p class="card-subtitle">${days.filter(d=>(h.logs||[]).includes(d)).length} of 7 days this week</p></section>`).join(''):empty('Start with one small habit','Choose something realistic that supports the person you want to become.',addBtn('Create a habit','add','habit'))}</div>`;}
function renderRoutines(){const routines=records('routine'),today=todayISO();return `${pageHeader('Routines','Create a rhythm that supports your mornings and evenings.',addBtn('Add routine','add','routine'))}<div class="grid grid-2">${routines.length?routines.map(r=>{const steps=Array.isArray(r.steps)?r.steps:String(r.steps||'').split('\n').filter(Boolean),checked=(r.checks||{})[today]||[];return `<section class="card"><div class="card-head"><div><h2 class="card-title">${recordText(r,r.title)}</h2><p class="card-subtitle">${enumText(`${r.period||'Custom'} routine`)} · ${checked.length}/${steps.length} completed today</p></div>${editDelete(r)}</div><div class="item-list">${steps.map((s,i)=>`<div class="list-row"><input type="checkbox" class="check" data-action="routine-check" data-id="${r.id}" data-index="${i}" ${checked.includes(i)?'checked':''}><div class="list-main"><strong>${recordText(r,s)}</strong></div></div>`).join('')}</div><div class="progress-track" style="margin-top:13px"><div class="progress-fill sage" style="width:${steps.length?checked.length/steps.length*100:0}%"></div></div></section>`}).join(''):empty('Design your daily rhythm','Create a morning, evening or custom routine with steps you can check off.',addBtn('Create a routine','add','routine'))}</div>`;}
async function imageURL(photoId){if(!photoId)return '';if(objectURLs.has(photoId))return objectURLs.get(photoId);const p=await LifeOSDB.getPhoto(photoId);if(!p?.blob)return '';const url=URL.createObjectURL(p.blob);objectURLs.set(photoId,url);return url;}
async function renderGlow(){const challenge=records('glow'),skincare=records('skincare'),before=records('glowPhoto').filter(x=>x.moment==='Before'),after=records('glowPhoto').filter(x=>x.moment==='After');let photoCards='';for(const p of [...before,...after]){const url=await imageURL(p.photoId);photoCards+=`<div class="vision-card">${url?`<img src="${url}" alt="${esc(p.title||p.moment)}" data-user-content>`:'<div class="photo-box">Photo stored locally</div>'}<div class="vision-card-body"><strong>${enumText(p.moment)} · ${esc(p.date||'')}</strong><div class="small muted">${recordText(p,p.notes||'')}</div>${editDelete(p)}</div></div>`;}return `${pageHeader('Glow Up','A 90-day space for routines, confidence and small acts of care.',`${addBtn('New challenge','add','glow')}${addBtn('Add skincare step','add','skincare','btn-secondary')}`)}<div class="grid grid-2"><div class="card"><div class="card-head"><h2 class="card-title">90-day challenge</h2><span class="tag">Your pace</span></div>${challenge.length?`<div class="item-list">${challenge.map(c=>{const start=dateObj(c.startDate),days=Math.max(0,Math.min(Number(c.duration||90),Math.floor((dateObj(todayISO())-start)/86400000)+1));return `<div class="list-row"><div class="list-main"><strong>${recordText(c,c.title)}</strong><small>${enumText('Started')} ${fmtDate(c.startDate)} · ${enumText('Day')} ${days} ${enumText('of')} ${Number(c.duration||90)}</small><div class="progress-track" style="margin-top:7px"><div class="progress-fill" style="width:${days/Number(c.duration||90)*100}%"></div></div></div>${editDelete(c)}</div>`}).join('')}</div>`:empty('Choose your 90-day intention','A challenge can be simple: consistency, rest, confidence or a new routine.',addBtn('Start a challenge','add','glow'))}</div><div class="card"><div class="card-head"><h2 class="card-title">Skincare routine</h2><button class="btn btn-secondary btn-small" data-action="add" data-type="skincare">＋ Add step</button></div>${skincare.length?`<div class="item-list">${skincare.map(s=>`<div class="list-row"><span class="tag sage">${enumText(s.frequency||'Daily')}</span><div class="list-main"><strong>${recordText(s,s.title)}</strong><small>${recordText(s,s.notes||'')}</small></div>${editDelete(s)}</div>`).join('')}</div>`:empty('Keep your routine simple','Add your AM, PM or weekly skincare steps.')}</div></div><div class="card" style="margin-top:15px"><div class="card-head"><div><h2 class="card-title">Self-care menu</h2><p class="card-subtitle">Choose a small reset that feels good today.</p></div></div><div class="grid grid-4">${['Take a slow walk','Read for 10 minutes','Stretch gently','Make a nourishing meal','Tidy one small space','Call someone you love','Take a screen break','Go to bed a little earlier'].map((x,i)=>`<button class="card" style="padding:12px;background:var(--surface-2);text-align:left" data-action="selfcare" data-value="${esc(x)}"><span style="font-size:18px">${['♡','▣','✧','♧','⌂','☏','☼','☾'][i]}</span><strong style="display:block;font-size:10px;margin-top:6px">${x}</strong><small class="muted">Tap to log</small></button>`).join('')}</div></div><div class="card" style="margin-top:15px"><div class="card-head"><div><h2 class="card-title">Before & after gallery</h2><p class="card-subtitle">Private photos stay in this browser profile.</p></div><div class="heading-actions"><button class="btn btn-secondary btn-small" data-action="photo" data-moment="Before">＋ Before photo</button><button class="btn btn-primary btn-small" data-action="photo" data-moment="After">＋ After photo</button></div></div><div class="vision-grid">${photoCards||empty('Your gallery is waiting','Add photos if you would like to document your journey.')}</div></div>`;}
function renderWellness(){const all=records('wellness'),cycle=records('cycle'),logs=all.filter(x=>x.date>=addDays(todayISO(),-13)&&x.date<=todayISO()),recent=logs.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20);return `${pageHeader('Wellness & Cycle','A personal log for noticing patterns. This is for record-keeping, not medical advice.',`${addBtn('Add check-in','add','wellness')}${addBtn('Log period dates','add','cycle','btn-secondary')}`)}<div class="grid grid-2"><div class="card"><div class="card-head"><h2 class="card-title">14-day wellness log</h2><span class="tag sage">Last 14 days</span></div>${recent.length?`<div class="item-list">${recent.map(r=>`<div class="list-row"><span class="tag ${r.kind==='Mood'?'':'sage'}">${enumText(r.kind)}</span><div class="list-main"><strong>${recordText(r,r.value)}</strong><small>${fmtDate(r.date)} ${r.notes?`· ${recordText(r,r.notes)}`:''}</small></div>${editDelete(r)}</div>`).join('')}</div>`:empty('Start with a check-in','Log mood, sleep, water, steps or a workout.',addBtn('Add check-in','add','wellness'))}</div><div class="card"><div class="card-head"><h2 class="card-title">Cycle history</h2><span class="tag">Manual records</span></div>${cycle.length?`<div class="item-list">${cycle.sort((a,b)=>b.startDate.localeCompare(a.startDate)).map(c=>`<div class="list-row"><div class="list-main"><strong>${fmtDate(c.startDate)}${c.endDate?` – ${fmtDate(c.endDate)}`:''}</strong><small>${recordText(c,c.symptoms||'No symptoms noted')} ${c.notes?`· ${recordText(c,c.notes)}`:''}</small></div>${editDelete(c)}</div>`).join('')}</div>`:empty('No cycle entries yet','Add dates manually if you want to keep a personal record.',addBtn('Log dates','add','cycle'))}<p class="card-subtitle" style="margin-top:12px">LifeOS does not predict ovulation, diagnose conditions or replace professional medical advice.</p></div></div><div class="card" style="margin-top:15px"><div class="card-head"><h2 class="card-title">Workout log</h2><button class="btn btn-secondary btn-small" data-action="add" data-type="wellness" data-kind="Workout">＋ Log workout</button></div>${all.filter(x=>x.kind==='Workout').length?`<div class="item-list">${all.filter(x=>x.kind==='Workout').slice(-8).reverse().map(x=>`<div class="list-row"><div class="list-main"><strong>${recordText(x,x.value)}</strong><small>${fmtDate(x.date)} · ${recordText(x,x.notes||'')}</small></div>${editDelete(x)}</div>`).join('')}</div>`:empty('Movement, your way','Record a workout, walk or stretch session.')}</div>`;}
function renderFinance(){
 const month=todayISO().slice(0,7),transactions=records('finance').filter(x=>(x.date||'').startsWith(month));
 const income=transactions.filter(x=>x.kind==='Income').reduce((a,x)=>a+Number(x.amount||0),0);
 const expense=transactions.filter(x=>x.kind==='Expense').reduce((a,x)=>a+Number(x.amount||0),0);
 const goals=records('financeGoal');
 const categoryBody=expense?(()=>{const sums={};transactions.filter(x=>x.kind==='Expense').forEach(x=>sums[x.category||'Other']=(sums[x.category||'Other']||0)+Number(x.amount));return Object.entries(sums).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="stat-line"><span>${enumText(k)}</span><strong>${money(v)}</strong></div>`).join('');})():empty('Your categories will appear here','Add an expense to see a breakdown.');
 const rate=income?`${((income-expense)/income*100).toFixed(1)}%`:'—';
 const transactionBody=transactions.length?`<div class="item-list">${transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="list-row"><span class="tag ${x.kind==='Income'?'sage':'gold'}">${enumText(x.kind)}</span><div class="list-main"><strong>${recordText(x,x.title)}</strong><small>${fmtDate(x.date)} · ${enumText(x.category||'Other')}</small></div><strong class="${x.kind==='Income'?'amount-positive':'amount-negative'}">${x.kind==='Income'?'+':'−'}${money(x.amount)}</strong>${editDelete(x)}</div>`).join('')}</div>`:empty('No transactions yet','Record income and expenses to see your monthly picture.',addBtn('Add transaction','add','finance'));
 const goalBody=goals.length?`<div class="item-list">${goals.map(g=>`<div class="list-row"><div class="list-main"><strong>${recordText(g,g.title)}</strong><small>${money(g.saved)} ${enumText('saved of')} ${money(g.target)}</small><div class="progress-track" style="margin-top:6px"><div class="progress-fill sage" style="width:${Math.max(0,Math.min(100,Number(g.target)?Number(g.saved)/Number(g.target)*100:0))}%"></div></div></div>${editDelete(g)}</div>`).join('')}</div>`:empty('Give a savings goal a name','Track a trip, buffer, purchase or another personal goal.',addBtn('Add savings goal','add','financeGoal'));
 return `${pageHeader('Finance','A calm, clear view of your household money.',`${addBtn('Add transaction','add','finance')}${addBtn('Savings goal','add','financeGoal','btn-secondary')}`)}
 <div class="grid grid-4" style="margin-bottom:15px">${metric('Income this month',money(income),'Money received','＋','sage')}${metric('Expenses this month',money(expense),'Money spent','−','gold')}${metric('Net balance',money(income-expense),'Income minus expenses','＄')}${metric('Monthly budget',money(state.settings.monthlyBudget||0),state.settings.monthlyBudget?`${Math.max(0,100-expense/Number(state.settings.monthlyBudget)*100).toFixed(0)}% remaining`:'Set a budget in settings','◎','lilac')}</div>
 <div class="grid grid-2"><div class="card"><div class="card-head"><h2 class="card-title">Transactions</h2><span class="tag">${month}</span></div>${transactionBody}</div><div class="grid" style="align-content:start">${card('Spending by category',`${categoryBody}<div class="stat-line"><span>Current savings rate</span><strong>${rate}</strong></div>`)}${card('Savings goals',goalBody)}</div></div>`;
}
function renderMeals(){const start=startOfWeek(todayISO()),weekDays=Array.from({length:7},(_,i)=>addDays(start,i)),meals=records('meal'),groceries=records('grocery'),recipes=records('recipe');return `${pageHeader('Meals & Groceries','Make the week a little easier with a plan you can adjust.',`${addBtn('Plan a meal','add','meal')}${addBtn('Add grocery','add','grocery','btn-secondary')}`)}<div class="card"><div class="card-head"><div><h2 class="card-title">This week’s meals</h2><p class="card-subtitle">${fmtDate(start)} – ${fmtDate(weekDays[6])}</p></div></div><div class="grid grid-2">${weekDays.map(d=>`<div class="card" style="padding:12px;background:var(--surface-2)"><strong style="font-size:10px">${dateObj(d).toLocaleDateString(LifeOSI18n.locale(),{weekday:'long',month:'short',day:'numeric'})}</strong>${['Breakfast','Lunch','Dinner'].map(type=>{const m=meals.find(x=>x.date===d&&x.meal===type);return `<div class="stat-line"><span>${enumText(type)}</span><strong>${m?recordText(m,m.recipe):'—'}</strong></div>`}).join('')}<button class="btn btn-secondary btn-small" style="margin-top:8px" data-action="add" data-type="meal" data-date="${d}">＋ Plan meal</button></div>`).join('')}</div></div><div class="grid grid-2" style="margin-top:15px"><div class="card"><div class="card-head"><h2 class="card-title">Grocery list</h2><span class="tag">${groceries.filter(g=>!g.done).length} remaining</span></div>${groceries.length?`<div class="item-list">${groceries.map(g=>`<div class="list-row"><input class="check" type="checkbox" data-action="toggle-grocery" data-id="${g.id}" ${g.done?'checked':''}><div class="list-main"><strong style="${g.done?'text-decoration:line-through;opacity:.5':''}">${recordText(g,g.title)}</strong><small>${enumText(g.category||'Other')}</small></div>${editDelete(g)}</div>`).join('')}</div>`:empty('Your list is clear','Add grocery items as you plan meals.',addBtn('Add grocery','add','grocery'))}</div><div class="card"><div class="card-head"><h2 class="card-title">Recipe cards</h2><button class="btn btn-secondary btn-small" data-action="add" data-type="recipe">＋ Add recipe</button></div>${recipes.length?`<div class="item-list">${recipes.map(r=>`<div class="list-row"><div class="list-main"><strong>${recordText(r,r.title)}</strong><small>${recordText(r,(r.ingredients||'').slice(0,95))}</small></div>${editDelete(r)}</div>`).join('')}</div>`:empty('Save a favorite recipe','Keep ingredients and instructions together.')}</div></div>`;}
async function renderGoals(){const goals=records('goal'),visions=records('vision').slice(0,12);let cards='';for(let i=0;i<12;i++){const v=visions[i];if(!v){cards+=`<button class="vision-card" data-action="add" data-type="vision" style="min-height:145px;background:var(--surface-2);border-style:dashed;cursor:pointer;text-align:center;color:var(--muted);padding:14px"><span style="font-size:22px">＋</span><strong style="display:block;font-size:10px;margin-top:7px">Add a vision</strong><small class="small">Photo or intention ${i+1}/12</small></button>`;continue;}const url=await imageURL(v.photoId);cards+=`<div class="vision-card">${url?`<img src="${url}" alt="${esc(v.title)}" data-user-content>`:'<div class="photo-box">＋ Add a vision image</div>'}<div class="vision-card-body"><strong>${recordText(v,v.title)}</strong><div class="small muted">${enumText(v.category||'Personal')}</div><div class="small muted">${recordText(v,v.notes||'')}</div>${editDelete(v)}<button class="btn btn-secondary btn-small" style="margin-top:7px" data-action="photo" data-record="${v.id}">Add / change photo</button></div></div>`;}return `${pageHeader('Goals & Vision','Give your intentions a place to live, then choose a next step.',`${addBtn('Add goal','add','goal')}${addBtn('Add vision item','add','vision','btn-secondary')}`)}<div class="grid grid-2"><div class="card"><div class="card-head"><h2 class="card-title">Goals & action steps</h2><span class="tag">${goals.length} goals</span></div>${goals.length?`<div class="item-list">${goals.map(g=>`<div class="list-row"><div class="list-main"><strong>${recordText(g,g.title)}</strong><small>${recordText(g,g.action||g.why||'Choose your next step')} · ${Number(g.progress||0)}%</small><input aria-label="Goal progress" type="range" min="0" max="100" value="${Number(g.progress||0)}" data-action="goal-progress" data-id="${g.id}" style="width:100%;accent-color:var(--accent);margin-top:6px"></div>${editDelete(g)}</div>`).join('')}</div>`:empty('Start with what matters','Add a goal and one small action you can take.',addBtn('Add a goal','add','goal'))}</div><div class="card"><div class="card-head"><h2 class="card-title">Vision board</h2><span class="tag sage">12-photo vision space</span></div><p class="card-subtitle" style="margin-bottom:12px">Add up to 12 images or intentions that represent the life you are building.</p><div class="small muted" style="margin-bottom:8px">Vision palette</div><div style="display:flex;gap:7px;margin-bottom:13px">${['#DFAFC0','#D4C2A7','#A7BDAA','#B9A9D2','#C77A86','#91A7BE'].map(c=>`<button title="Choose palette" data-action="vision-color" data-color="${c}" style="width:22px;height:22px;border-radius:50%;border:2px solid ${state.settings.visionPalette===c?'var(--ink)':'white'};background:${c};box-shadow:0 0 0 1px var(--line)"></button>`).join('')}</div><div class="vision-grid">${cards}</div></div></div>`;}
function renderJournal(){const entries=records('journal').sort((a,b)=>b.date.localeCompare(a.date));return `${pageHeader('Journal','A quiet place to notice, reflect and remember.',addBtn('New journal entry','add','journal'))}<div class="grid grid-2"><div class="card"><div class="card-head"><h2 class="card-title">Writing prompts</h2><span class="tag">A gentle nudge</span></div><div class="item-list">${['What felt like a small win today?','What do I need more of this week?','What am I grateful for right now?','What can I release or make lighter?','What would I tell a friend in my situation?'].map(p=>`<div class="list-row"><div class="list-main"><strong>${p}</strong></div><button class="icon-action" data-action="prompt" data-value="${esc(p)}">Use ↗</button></div>`).join('')}</div></div><div class="card"><div class="card-head"><h2 class="card-title">Gratitude corner</h2></div><form id="gratitudeForm" class="form-grid"><div class="field full"><label>Three things I appreciate</label><textarea name="gratitude" rows="5" placeholder="1. ...&#10;2. ...&#10;3. ..."></textarea></div><div class="field full"><button class="btn btn-primary">Save gratitude note</button></div></form></div></div><div class="card" style="margin-top:15px"><div class="card-head"><h2 class="card-title">Past entries</h2><span class="tag">${entries.length} entries</span></div>${entries.length?`<div class="item-list">${entries.map(e=>`<div class="list-row"><div class="list-main"><strong>${e.title?recordText(e,e.title):fmtDate(e.date)}</strong><small>${fmtDate(e.date)} · ${enumText(e.mood||'No mood')} · ${recordText(e,(e.content||e.gratitude||'').slice(0,110))}</small></div>${editDelete(e)}</div>`).join('')}</div>`:empty('Your story starts here','Create a journal entry whenever you want to pause and reflect.',addBtn('Write an entry','add','journal'))}</div>`;}
function renderReading(){const books=records('book'),finished=books.filter(b=>b.status==='Finished').length,goal=Number(state.settings.readingGoal||12);return `${pageHeader('Reading List','Keep your next chapter close.',addBtn('Add a book','add','book'))}<div class="grid grid-3" style="margin-bottom:15px">${metric('Books in library',books.length,'Saved titles','▣')}${metric('Finished',finished,'Completed reads','✧','sage')}${metric('Yearly reading goal',`${finished}/${goal}`,`${Math.min(100,finished/Math.max(1,goal)*100).toFixed(0)}% of your goal`,'♡','gold')}</div><div class="card"><div class="card-head"><h2 class="card-title">Your bookshelf</h2><span class="tag">${books.length} titles</span></div>${books.length?`<div class="item-list">${books.map(b=>`<div class="book-row"><div><strong style="font-size:11px">${recordText(b,b.title)}</strong><div class="small muted">${recordText(b,b.author||'Unknown author')} · ${enumText(b.status||'Want to read')}</div><div class="book-stars">${'★'.repeat(Math.max(0,Math.min(5,Number(b.rating||0))))}${'☆'.repeat(5-Math.max(0,Math.min(5,Number(b.rating||0))))}</div></div>${editDelete(b)}</div>`).join('')}</div>`:empty('Make room for a good book','Add books you want to read, are reading or have finished.',addBtn('Add a book','add','book'))}</div>`;}
async function renderOutfits(){const outfits=records('outfit').sort((a,b)=>b.date.localeCompare(a.date)),wish=records('wishlist');let cards='';for(const o of outfits){const url=await imageURL(o.photoId);cards+=`<div class="vision-card">${url?`<img src="${url}" alt="${esc(o.title)}" data-user-content>`:'<div class="photo-box">Outfit photo</div>'}<div class="vision-card-body"><strong>${recordText(o,o.title)}</strong><div class="small muted">${fmtDate(o.date)} · ${recordText(o,o.notes||'')}</div>${editDelete(o)}<button class="btn btn-secondary btn-small" data-action="photo" data-record="${o.id}" style="margin-top:7px">Add / change photo</button></div></div>`;}return `${pageHeader('OOTD & Wishlist','Save outfit ideas and keep a thoughtful wishlist.',`${addBtn('Add outfit','add','outfit')}${addBtn('Add wishlist item','add','wishlist','btn-secondary')}`)}<div class="grid grid-2"><div class="card"><div class="card-head"><h2 class="card-title">Outfit diary</h2><span class="tag">${outfits.length} looks</span></div><div class="vision-grid">${cards||empty('Your outfit diary','Add an outfit and attach a photo from your device.',addBtn('Add outfit','add','outfit'))}</div></div><div class="card"><div class="card-head"><h2 class="card-title">Wishlist</h2><span class="tag">${wish.filter(x=>!x.purchased).length} saved</span></div>${wish.length?`<div class="item-list">${wish.map(w=>`<div class="list-row"><div class="list-main"><strong>${recordText(w,w.title)}</strong><small>${enumText(w.category||'Other')} · ${w.price?money(w.price):enumText('Price not set')} ${w.purchased?`· ${enumText('Purchased')}`:''}</small>${w.url?`<a href="${esc(w.url)}" target="_blank" rel="noopener" class="small">Open link</a>`:''}</div><button class="icon-action" data-action="purchase" data-id="${w.id}" title="Mark purchased">✓</button>${editDelete(w)}</div>`).join('')}</div>`:empty('Keep a thoughtful wishlist','Save items you are considering, with a price or link.',addBtn('Add wishlist item','add','wishlist'))}</div></div>`;}
function renderSettings(){const s=state.settings;return `${pageHeader('Settings & Backup','Make LifeOS feel like your own, and keep a safe copy of your data.')}<div class="settings-layout"><div class="card settings-main-card"><div class="card-head"><div><p class="eyebrow">YOUR SPACE</p><h2 class="card-title">Personalization</h2><p class="card-subtitle">Choose how LifeOS looks, feels and speaks to you.</p></div><span class="tag sage">Personal settings</span></div>
 <div class="settings-section-title" data-i18n="profileSection">Profile</div><div class="setting-row"><div><strong data-i18n="profilePhoto">Profile photo</strong><small data-i18n="profilePhotoHelp">Upload a square JPG, PNG or WebP image. It stays private in this browser and is included in backups.</small></div><div class="profile-settings-control"><div class="profile-photo-preview" id="profilePhotoPreview"><span>${esc((s.name||'U').trim()[0]||'U')}</span></div><div class="profile-photo-actions"><button type="button" class="btn btn-secondary btn-small" data-action="profile-photo">${s.profilePhotoId?'<span data-i18n="changePhoto">Change photo</span>':'<span data-i18n="uploadProfilePhoto">Upload profile photo</span>'}</button>${s.profilePhotoId?'<button type="button" class="btn btn-danger btn-small" data-action="remove-profile-photo"><span data-i18n="removePhoto">Remove</span></button>':''}</div></div></div>
 <div class="setting-row"><div><strong>Your name</strong><small>Used for your greeting and profile.</small></div><div class="setting-control"><input id="settingName" value="${esc(s.name||'')}" placeholder="Your name"></div></div>
 <div class="settings-section-title">Appearance</div><div class="setting-row"><div><strong>Color theme</strong><small>Changes the background, sidebar, cards, icons, progress indicators, forms and buttons.</small></div><div class="setting-control"><select id="settingTheme"><option value="blush" ${s.theme==='blush'?'selected':''}>Blush</option><option value="latte" ${s.theme==='latte'?'selected':''}>Latte</option><option value="sage" ${s.theme==='sage'?'selected':''}>Sage</option><option value="lilac" ${s.theme==='lilac'?'selected':''}>Lilac</option><option value="cherry" ${s.theme==='cherry'?'selected':''}>Cherry</option><option value="dark" ${s.theme==='dark'?'selected':''}>Dark mode</option></select></div></div>
 <div class="setting-row"><div><strong>Text size</strong><small>Choose a comfortable reading size. Extra large is the default.</small></div><div class="setting-control"><select id="settingFontSize"><option value="small" ${s.fontSize==='small'?'selected':''}>Small</option><option value="standard" ${s.fontSize==='standard'?'selected':''}>Standard</option><option value="large" ${s.fontSize==='large'?'selected':''}>Large</option><option value="extra-large" ${(s.fontSize||'extra-large')==='extra-large'?'selected':''}>Extra large</option></select></div></div>
 <div class="setting-row"><div><strong>Layout spacing</strong><small>Choose more breathing room or a compact layout.</small></div><div class="setting-control"><select id="settingDensity"><option value="compact" ${s.density==='compact'?'selected':''}>Compact</option><option value="comfortable" ${(s.density||'comfortable')==='comfortable'?'selected':''}>Comfortable</option><option value="spacious" ${s.density==='spacious'?'selected':''}>Spacious</option></select></div></div>
 <div class="setting-row"><div><strong>Language</strong><small>Changes the language across every planner screen, module, label and control.</small></div><div class="setting-control"><select id="settingLanguage"><option value="en" ${s.language==='en'?'selected':''}>English</option><option value="es" ${s.language==='es'?'selected':''}>Español</option><option value="fr" ${s.language==='fr'?'selected':''}>Français</option><option value="de" ${s.language==='de'?'selected':''}>Deutsch</option><option value="ar" ${s.language==='ar'?'selected':''}>العربية</option></select></div></div>
 <div class="settings-section-title">Planner preferences</div><div class="setting-row"><div><strong>Currency</strong><small>Used for finance amounts and goals.</small></div><div class="setting-control"><select id="settingCurrency">${['USD','GBP','EUR','CAD','AUD','PKR','AED','SAR'].map(c=>`<option ${s.currency===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="setting-row"><div><strong>Planner year</strong><small>Used by the year overview.</small></div><div class="setting-control"><select id="settingYear">${[2026,2027,2028,2029,2030].map(y=>`<option ${Number(s.year)===y?'selected':''}>${y}</option>`).join('')}</select></div></div><div class="setting-row"><div><strong>Monthly budget</strong><small>Used in your finance overview.</small></div><div class="setting-control"><input id="settingBudget" type="number" min="0" step="0.01" value="${Number(s.monthlyBudget||0)}"></div></div><div class="setting-row"><div><strong>Annual reading goal</strong><small>Books you would like to finish.</small></div><div class="setting-control"><input id="settingReadingGoal" type="number" min="1" max="365" value="${Number(s.readingGoal||12)}"></div></div><div class="settings-save-row"><button class="btn btn-primary" data-action="save-settings">Save preferences</button></div>
 </div><div class="settings-side-column"><div class="card"><div class="card-head"><div><p class="eyebrow">KEEP IT SAFE</p><h2 class="card-title">Backup & restore</h2></div><span class="tag sage">Recommended</span></div><p class="card-subtitle setting-help">Your information is stored in this browser on this device. Export a backup before changing devices, clearing browser data or moving to another browser.</p><button class="btn btn-primary settings-wide-button" data-action="export-backup">↓ Export full backup (JSON)</button><button class="btn btn-secondary settings-wide-button" data-action="import-backup">↑ Import a LifeOS backup</button><div class="privacy-note settings-privacy"><span class="privacy-dot"></span><div><strong>Local-first privacy</strong><small>No account, cloud sync, analytics or remote server is used.</small></div></div></div><div class="card"><div class="card-head"><div><p class="eyebrow">EXPLORE</p><h2 class="card-title">Print & demo</h2></div></div><p class="card-subtitle setting-help">Print the current screen or add sample entries to explore the planner.</p><div class="settings-button-grid"><button class="btn btn-secondary" data-action="print">Print current page</button><button class="btn btn-secondary" data-action="demo">Load demo data</button><button class="btn btn-danger" data-action="clear-data">Clear all planner data</button></div></div><div class="card"><div class="card-head"><div><p class="eyebrow">ABOUT</p><h2 class="card-title">LifeOS</h2></div><span class="soft-icon">✧</span></div><p class="card-subtitle setting-help">Your private, offline personal planning space. Keep a current backup so your photos and entries can move with you.</p><span class="tag">LifeOS Offline Edition · v1.3</span></div></div></div>`;}
async function render(){applyTheme();navActive();let html='';switch(route){case'dashboard':html=await renderDashboard();break;case'today':html=await renderToday();break;case'week':html=renderWeek();break;case'month':html=renderMonth();break;case'year':html=renderYear();break;case'habits':html=renderHabits();break;case'routines':html=renderRoutines();break;case'glow':html=await renderGlow();break;case'wellness':html=renderWellness();break;case'finance':html=renderFinance();break;case'meals':html=renderMeals();break;case'goals':html=await renderGoals();break;case'journal':html=renderJournal();break;case'reading':html=renderReading();break;case'outfits':html=await renderOutfits();break;case'settings':html=renderSettings();break;default:html=await renderDashboard();route='dashboard';}$('#content').innerHTML=html;LifeOSI18n.apply($('#content'));await updateHeader();if(route==='settings')await updateProfilePreview();navActive();}
function fieldHTML(field,value){const [name,label,type,requiredOrOptions]=field;const required=requiredOrOptions===true?'required':'';const options=Array.isArray(requiredOrOptions)?requiredOrOptions:null;let control='';if(type==='textarea')control=`<textarea name="${name}" ${required} placeholder="Add details…">${esc(Array.isArray(value)?value.map(x=>LifeOSI18n.tx(String(x))).join('\n'):value||'')}</textarea>`;else if(type==='select')control=`<select name="${name}" ${required}>${(options||[]).map(x=>`<option value="${esc(x)}" ${String(value)===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;else control=`<input name="${name}" type="${type}" value="${esc(value??'')}" ${required} ${type==='number'?'step="any"':''} ${type==='number'?'min="0"':''}>`;return `<div class="field ${type==='textarea'?'full':''}"><label>${esc(label)}${required?' *':''}</label>${control}</div>`;}
function openForm(type,recordId=null,preset={}){if(type==='vision'&&!recordId&&records('vision').length>=12){toast('Your vision board has 12 spaces. Edit or remove an existing item first.','error');return;}const def=definitions[type];if(!def){toast('This form is not available.','error');return;}const existing=recordId?byId(recordId):null;$('#modalEyebrow').textContent=LifeOSI18n.tx(`LIFEOS · ${type.toUpperCase()}`);$('#modalTitle').textContent=`${existing?t('edit'):t('add')} ${LifeOSI18n.tx(def.title)}`;$('#modalBody').innerHTML=`<form id="recordForm" class="form-grid">${def.fields.map(f=>fieldHTML(f,formDisplayValue(existing,f[0],existing?.[f[0]],f[2])??preset[f[0]]??(f[0]==='date'?selectedDate:f[0]==='startDate'?todayISO():f[0]==='weekStart'?startOfWeek(todayISO()):f[0]==='duration'?90:f[0]==='kind'&&preset.kind?preset.kind:''))).join('')}<input type="hidden" name="recordType" value="${type}"></form>`;$('#modalFoot').innerHTML=`<button class="btn btn-secondary" data-action="modal-cancel">${t('cancel')}</button><button class="btn btn-primary" data-action="modal-save">${t('save')}</button>`;activeModalSave=async()=>{const form=$('#recordForm');if(!form.reportValidity())return;const fd=new FormData(form),data={};for(const [k,v] of fd.entries())if(k!=='recordType')data[k]=v;if(type==='routine')data.steps=String(data.steps||'').split('\n').map(x=>x.trim()).filter(Boolean);if(type==='finance'||type==='financeGoal'||type==='goal'||type==='book'||type==='glow')for(const k of ['amount','target','saved','progress','rating','duration'])if(data[k]!==undefined)data[k]=Number(data[k]||0);if(existing){Object.assign(existing,data);existing.demo=false;existing.systemText=false;existing.updatedAt=new Date().toISOString();}else{const rec={id:id(),type,...data,createdAt:new Date().toISOString()};if(type==='habit')rec.logs=[];if(type==='routine')rec.checks={};if(type==='grocery')rec.done=false;if(type==='vision'&&preset.photoId)rec.photoId=preset.photoId;state.records.push(rec);}await persist();closeModal();toast(t('saved'));await render();};LifeOSI18n.apply($('#modalBackdrop'));$('#modalBackdrop').hidden=false;setTimeout(()=>$('#modalBody input:not([type=hidden]),#modalBody textarea,#modalBody select')?.focus(),20);}
function closeModal(){$('#modalBackdrop').hidden=true;activeModalSave=null;}
async function removeRecord(recordId){const r=byId(recordId);if(!r)return;if(!confirm(t('confirmDelete')))return;state.records=state.records.filter(x=>x.id!==recordId);if(r.photoId)await LifeOSDB.deletePhoto(r.photoId);await persist();toast(t('saved'));await render();}
async function photoFlow(recordId=null,moment=null){photoTarget={recordId,moment,profile:moment==='profile'};$('#photoInput').value='';$('#photoInput').click();}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);}
async function exportBackup(){try{const payload=await LifeOSDB.exportBackup(state);downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`LifeOS-Backup-${todayISO()}.json`);toast(t('backupDone'));}catch(e){toast('Backup could not be created.','error');}}
function importBackup(){ $('#restoreInput').value='';$('#restoreInput').click(); }
async function loadDemo(){if(state.records.length&&!confirm(LifeOSI18n.tx('Demo entries will be added to your existing planner. Continue?')))return;const now=todayISO(),tomorrow=addDays(now,1);const demo=[
 {type:'task',title:'Choose my top three priorities',date:now,time:'09:00',priority:'High',category:'Personal',done:false},
 {type:'task',title:'Plan meals for the week',date:now,time:'11:30',priority:'Normal',category:'Home',done:false},
 {type:'event',title:'Coffee with a friend',date:tomorrow,time:'15:00',kind:'Personal',notes:'A little time to reconnect.'},
 {type:'habit',title:'Drink more water',category:'Health',logs:[now,addDays(now,-1),addDays(now,-2)]},
 {type:'habit',title:'Read for 15 minutes',category:'Personal',logs:[addDays(now,-1)]},
 {type:'routine',title:'Gentle morning',period:'Morning',steps:['Drink a glass of water','Open the curtains','Review today’s priorities','Take five quiet minutes'],checks:{}},
 {type:'finance',kind:'Income',date:now,title:'Monthly income',amount:3200,category:'Work'},
 {type:'finance',kind:'Expense',date:now,title:'Weekly groceries',amount:82.5,category:'Food'},
 {type:'financeGoal',title:'Weekend getaway',target:600,saved:180,dueDate:addDays(now,90)},
 {type:'meal',date:now,meal:'Dinner',recipe:'Roasted vegetables and rice'},
 {type:'grocery',title:'Oat milk',category:'Dairy',done:false},
 {type:'goal',title:'Create a calmer morning',why:'Start the day with less rushing.',action:'Prepare tomorrow’s bag tonight.',progress:35,dueDate:addDays(now,45)},
 {type:'journal',date:now,title:'A small start',mood:'Hopeful',gratitude:'A quiet cup of tea and a fresh page.',content:'I want to make room for steady, meaningful progress.'},
 {type:'book',title:'The Creative Act',author:'Rick Rubin',status:'Currently reading',rating:0},
 {type:'wellness',kind:'Mood',date:now,value:'Hopeful',notes:'Demo check-in'},
 {type:'weekly',weekStart:startOfWeek(now),focus:'Make space for one important thing each day.',review:''}
 ];demo.forEach(x=>state.records.push({id:id(),...x,demo:true,createdAt:new Date().toISOString()}));await persist();await render();toast('Demo data added.');}
async function saveSettings(){state.settings.name=$('#settingName').value.trim()||'Your space';state.settings.theme=$('#settingTheme').value;state.settings.language=$('#settingLanguage').value;state.settings.currency=$('#settingCurrency').value;state.settings.year=Number($('#settingYear').value);state.settings.monthlyBudget=Number($('#settingBudget').value||0);state.settings.readingGoal=Number($('#settingReadingGoal').value||12);state.settings.fontSize=$('#settingFontSize').value;state.settings.density=$('#settingDensity').value;await persist();applyTheme();await render();toast('Preferences saved.');}
function toggleHabit(recordId,date){const h=byId(recordId);if(!h)return;h.logs=h.logs||[];h.logs=h.logs.includes(date)?h.logs.filter(x=>x!==date):[...h.logs,date];persist().then(render);}
function toggleRoutine(recordId,index){const r=byId(recordId);if(!r)return;r.checks=r.checks||{};r.checks[todayISO()]=r.checks[todayISO()]||[];const arr=r.checks[todayISO()];r.checks[todayISO()]=arr.includes(index)?arr.filter(x=>x!==index):[...arr,index];persist().then(render);}
function toggleGrocery(recordId){const r=byId(recordId);if(!r)return;r.done=!r.done;persist().then(render);}
function openQuick(){const choices=[['Task','task'],['Event','event'],['Habit','habit'],['Wellness check-in','wellness'],['Money transaction','finance'],['Journal entry','journal']];$('#modalEyebrow').textContent=LifeOSI18n.tx('LIFEOS · QUICK ADD');$('#modalTitle').textContent=LifeOSI18n.tx('What would you like to add?');$('#modalBody').innerHTML=`<div class="grid grid-2">${choices.map(([label,type])=>`<button class="card" style="text-align:left;cursor:pointer;background:var(--surface-2)" data-action="quick-type" data-type="${type}"><strong>${label}</strong><small class="muted">Create a new ${label.toLowerCase()}</small></button>`).join('')}</div>`;$('#modalFoot').innerHTML=`<button class="btn btn-secondary" data-action="modal-cancel">${t('close')}</button>`;LifeOSI18n.apply($('#modalBackdrop'));$('#modalBackdrop').hidden=false;}
function routeTo(r){route=r;$('#sidebar').classList.remove('open');render();}
async function handleAction(el){const action=el.dataset.action,type=el.dataset.type,idValue=el.dataset.id;switch(action){
 case'add':openForm(type,null,{date:el.dataset.date||selectedDate,kind:el.dataset.kind||undefined});break;
 case'open-route':routeTo(el.dataset.route||'dashboard');break;
 case'quick-theme':state.settings.theme=el.dataset.theme||'blush';await persist();applyTheme();if(route==='settings')await render();toast('Theme updated.');break;
 case'edit':openForm(byId(idValue)?.type,idValue);break;
 case'delete':removeRecord(idValue);break;
 case'toggle-task':{const r=byId(idValue);if(r){r.done=el.checked;await persist();if(route==='today'||route==='dashboard')render();}}break;
 case'habit-day':toggleHabit(idValue,el.dataset.date);break;
 case'toggle-habit':toggleHabit(idValue,todayISO());break;
 case'routine-check':toggleRoutine(idValue,Number(el.dataset.index));break;
 case'toggle-grocery':toggleGrocery(idValue);break;
 case'goal-progress':{const r=byId(idValue);if(r){r.progress=Number(el.value);persist();const label=el.closest('.list-row')?.querySelector('.small');if(label)label.textContent=`${r.action||r.why||'Choose your next step'} · ${r.progress}%`;}}break;
 case'modal-cancel':closeModal();break;
 case'modal-save':if(activeModalSave)await activeModalSave();break;
 case'quick-type':closeModal();openForm(type);break;
 case'select-date':selectedDate=el.dataset.date;render();break;
 case'month-prev':{const d=dateObj(selectedDate);d.setMonth(d.getMonth()-1);selectedDate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;render();}break;
 case'month-next':{const d=dateObj(selectedDate);d.setMonth(d.getMonth()+1);selectedDate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;render();}break;
 case'month-today':selectedDate=todayISO();render();break;
 case'open-month':selectedDate=`${Number(state.settings.year)}-${String(Number(el.dataset.month)+1).padStart(2,'0')}-01`;routeTo('month');break;
 case'save-focus':{const v=$('#dailyFocus').value;let r=records('dailyFocus').find(x=>x.date===todayISO());if(!r){r={id:id(),type:'dailyFocus',date:todayISO()};state.records.push(r);}r.text=v;await persist();toast(t('saved'));}break;
 case'print':window.print();break;
 case'export-backup':await exportBackup();break;
 case'import-backup':importBackup();break;
 case'demo':await loadDemo();break;
 case'clear-data':if(confirm(LifeOSI18n.tx('This will remove all LifeOS entries and photos from this browser. Export a backup first if you need one. Continue?'))){state.records=[];const photos=await LifeOSDB.allPhotos();for(const p of photos)await LifeOSDB.deletePhoto(p.id);state.settings.profilePhotoId='';await persist();await render();toast('Planner data cleared.');}break;
 case'save-settings':await saveSettings();break;
 case'photo':await photoFlow(el.dataset.record||null,el.dataset.moment||'Vision');break;
 case'profile-photo':await photoFlow(null,'profile');break;
 case'remove-profile-photo':if(state.settings.profilePhotoId){await LifeOSDB.deletePhoto(state.settings.profilePhotoId);state.settings.profilePhotoId='';await persist();await render();toast('Profile photo removed.');}break;
 case'selfcare':{state.records.push({id:id(),type:'wellness',kind:'Self-care',date:todayISO(),value:el.dataset.value,notes:'Logged from the self-care menu.',systemText:true});await persist();toast('Self-care moment logged.');}break;
 case'prompt':routeTo('journal');openForm('journal',null,{date:todayISO(),title:el.dataset.value});break;
 case'purchase':{const r=byId(idValue);if(r){r.purchased=!r.purchased;await persist();render();}}break;
 case'vision-color':state.settings.visionPalette=el.dataset.color;await persist();render();break;
 case'modal-close':closeModal();break;
 }}
$('#sidebar').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b)routeTo(b.dataset.route);});
$('#content').addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)handleAction(el);});
$('#content').addEventListener('change',e=>{if(e.target.id==='yearSelect'){state.settings.year=Number(e.target.value);persist().then(render);}});
$('#content').addEventListener('submit',async e=>{if(e.target.id==='weeklyForm'){e.preventDefault();const fd=new FormData(e.target);let r=records('weekly').find(x=>x.weekStart===startOfWeek(todayISO()));if(!r){r={id:id(),type:'weekly',weekStart:startOfWeek(todayISO())};state.records.push(r);}r.focus=fd.get('focus');r.review=fd.get('review');await persist();toast(t('saved'));}if(e.target.id==='gratitudeForm'){e.preventDefault();const fd=new FormData(e.target);state.records.push({id:id(),type:'journal',date:todayISO(),title:'Gratitude note',gratitude:fd.get('gratitude'),mood:'Grateful',systemText:true});await persist();await render();toast(t('saved'));}});
$('#quickAdd').addEventListener('click',openQuick);$('#openSettings').addEventListener('click',()=>routeTo('settings'));$('#topProfile').addEventListener('click',()=>routeTo('settings'));$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#closeModal').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{const actionEl=e.target.closest('[data-action]');if(actionEl){handleAction(actionEl);return;}if(e.target===$('#modalBackdrop'))closeModal();});
$('#restoreInput').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(state.records.length&&!confirm(LifeOSI18n.tx('Importing a backup replaces the planner data currently stored in this browser. Export a backup first if you want to keep it. Continue?'))){e.target.value='';return;}try{const payload=JSON.parse(await file.text());state=await LifeOSDB.importBackup(payload);window.LifeOSSettings=state.settings;await updateHeader();applyTheme();await render();toast(t('restoreDone'));}catch(err){console.error(err);toast(t('invalidBackup'),'error');}});
$('#photoInput').addEventListener('change',async e=>{
 const file=e.target.files?.[0],target=photoTarget;photoTarget=null;if(!file||!target)return;
 if(!file.type.startsWith('image/')){toast('Please choose an image file.','error');return;}
 if(file.size>8*1024*1024){toast('Choose an image under 8 MB.','error');return;}
 const photoId=`p_${id()}`;await LifeOSDB.savePhoto(photoId,file,{name:file.name,type:file.type,size:file.size});
 if(target.profile){if(state.settings.profilePhotoId)await LifeOSDB.deletePhoto(state.settings.profilePhotoId);state.settings.profilePhotoId=photoId;}
 else if(target.recordId){const r=byId(target.recordId);if(r){if(r.photoId)await LifeOSDB.deletePhoto(r.photoId);r.photoId=photoId;}}
 else if(target.moment){state.records.push({id:id(),type:'glowPhoto',photoId,moment:target.moment,date:todayISO(),title:target.moment,notes:''});}
 await persist();await render();toast(target.profile?'Profile photo saved on this device.':'Photo saved on this device.');
});
$('#content').addEventListener('input',e=>{if(e.target.matches('[data-action="goal-progress"]')){const r=byId(e.target.dataset.id);if(r){r.progress=Number(e.target.value);LifeOSDB.saveState(state);}}});
$('#content').addEventListener('click',e=>{if(e.target.id==='settingTheme'||e.target.id==='settingLanguage')return;});
$('#content').addEventListener('change',e=>{if(e.target.id==='settingTheme'){state.settings.theme=e.target.value;applyTheme();}if(e.target.id==='settingLanguage'){state.settings.language=e.target.value;persist().then(async()=>{applyTheme();await render();toast('Language preference saved.');});}if(e.target.id==='settingFontSize'){state.settings.fontSize=e.target.value;applyTheme();}if(e.target.id==='settingDensity'){state.settings.density=e.target.value;applyTheme();}});
$('#topLanguage')?.addEventListener('change',async e=>{state.settings.language=e.target.value;await persist();applyTheme();await render();toast('Language preference saved.');});
$('#topbarThemes')?.addEventListener('click',e=>{const b=e.target.closest('[data-theme]');if(!b)return;state.settings.theme=b.dataset.theme;persist().then(async()=>{applyTheme();await render();toast('Theme updated.');});});
$('#modalBody').addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openQuick();}});
async function init(){const loaded=await LifeOSDB.loadState();if(loaded&&Array.isArray(loaded.records))state=loaded;else await LifeOSDB.saveState(state);window.LifeOSSettings=state.settings;applyTheme();LifeOSI18n.apply(document);await render();}
function scheduleDashboardClockRefresh(){
 const now=new Date(),candidates=[new Date(now.getFullYear(),now.getMonth(),now.getDate(),12,0,1),new Date(now.getFullYear(),now.getMonth(),now.getDate(),18,0,1),new Date(now.getFullYear(),now.getMonth(),now.getDate()+1,0,0,1)].filter(d=>d.getTime()>now.getTime());
 const next=candidates.sort((a,b)=>a-b)[0]||new Date(now.getFullYear(),now.getMonth(),now.getDate()+1,0,0,1);
 window.setTimeout(async()=>{if(route==='dashboard')await render();scheduleDashboardClockRefresh();},Math.max(1000,next.getTime()-now.getTime()));
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&route==='dashboard')render();});
init().catch(err=>{console.error(err);$('#content').innerHTML=`<div class="card">${LifeOSI18n.tx('LifeOS could not open its local data store. Try opening this folder in Chrome or Edge.')}</div>`;});
scheduleDashboardClockRefresh();
})();
